<template><view v-if="open" class="warm-overlay" @click.self="$emit('close')"><view class="warm-dialog" role="dialog" aria-modal="true" :aria-label="title" @keydown.esc="$emit('close')"><view class="dialog-head"><text>{{title}}</text><button class="dialog-close" aria-label="关闭弹窗" @click="$emit('close')">×</button></view><scroll-view scroll-y class="dialog-body"><slot/></scroll-view></view></view></template>
<script setup>defineProps({open:Boolean,title:String});defineEmits(['close']);</script>
<style scoped>.warm-overlay{position:fixed;inset:0;background:#49352166;z-index:500;display:flex;align-items:center;justify-content:center;padding:28rpx}.warm-dialog{width:100%;max-width:720rpx;box-sizing:border-box;padding:28rpx;background:#fffaf0;border:3rpx solid #e9c77d;border-radius:32rpx;box-shadow:0 18rpx 65rpx #64452130}.dialog-head{display:flex;align-items:center;justify-content:space-between;gap:16rpx;color:#6c502b;font-weight:700;font-size:30rpx;margin-bottom:20rpx}.dialog-close{width:66rpx;height:66rpx;padding:0;background:#faebc8;color:#7b5b2f;font-size:38rpx;line-height:60rpx}.dialog-body{max-height:65vh}</style>
<style scoped>/* #ifdef H5 */@media(min-width:1000px){.warm-dialog .dialog-head{font-size:22px}.warm-dialog .dialog-close{width:38px;height:38px;line-height:34px;font-size:28px}}/* #endif */</style>
